import express from "express";
import { Parser } from "expr-eval";

const app = express();
app.use(express.json());

/**
 * Safely evaluate a rule expression against a caller-supplied context.
 *
 * Uses expr-eval, which parses a strict mathematical/logical expression
 * grammar. It has NO access to the Node.js runtime, the file system, or
 * any global objects — so there is no code-injection risk regardless of
 * what the caller supplies as `rule`.
 *
 * Supported operators / constructs (expr-eval grammar):
 *   arithmetic : + - * / % ^
 *   comparison : == != < <= > >=
 *   logical    : and, or, not
 *   ternary    : condition ? a : b
 *   built-ins  : abs, ceil, floor, round, min, max, etc.
 *
 * @param {string} rule    - Expression string, e.g. "amount > 100"
 * @param {object} context - Key/value pairs referenced in the expression.
 * @returns {*} Result of the expression (typically boolean).
 * @throws  {Error} If the expression is syntactically invalid.
 */
function evalRule(rule, context) {
  const parser = new Parser();
  const expr = parser.parse(rule);
  return expr.evaluate(context);
}

/**
 * POST /check
 *
 * Request body (JSON):
 * {
 *   "rule":    "<expression>",   // required — e.g. "amount > 100"
 *   "context": { ... }           // required — variables referenced by rule
 * }
 *
 * Success response 200:
 * { "result": <boolean|number|string> }
 *
 * Error response 400 — missing fields or invalid expression syntax:
 * { "error": "<message>" }
 */
app.post("/check", (req, res) => {
  const { rule, context } = req.body;

  if (typeof rule !== "string" || rule.trim() === "") {
    return res
      .status(400)
      .json({ error: '`rule` must be a non-empty string.' });
  }

  if (context === undefined || context === null || typeof context !== "object" || Array.isArray(context)) {
    return res
      .status(400)
      .json({ error: '`context` must be a plain object.' });
  }

  try {
    const result = evalRule(rule, context);
    return res.status(200).json({ result });
  } catch (err) {
    return res
      .status(400)
      .json({ error: `Invalid rule expression: ${err.message}` });
  }
});

export default app;

import request from "supertest";
import app from "./app.js";

describe("POST /check", () => {
  // --- happy-path -----------------------------------------------------------

  test("returns true when rule evaluates to true", async () => {
    const res = await request(app)
      .post("/check")
      .send({ rule: "amount > 100", context: { amount: 150 } });

    expect(res.status).toBe(200);
    expect(res.body).toEqual({ result: true });
  });

  test("returns false when rule evaluates to false", async () => {
    const res = await request(app)
      .post("/check")
      .send({ rule: "amount > 100", context: { amount: 50 } });

    expect(res.status).toBe(200);
    expect(res.body).toEqual({ result: false });
  });

  test("supports compound logical expressions", async () => {
    const res = await request(app)
      .post("/check")
      .send({ rule: "score >= 80 and tier == 1", context: { score: 90, tier: 1 } });

    expect(res.status).toBe(200);
    expect(res.body).toEqual({ result: true });
  });

  test("supports arithmetic expressions", async () => {
    const res = await request(app)
      .post("/check")
      .send({ rule: "price * qty", context: { price: 5, qty: 3 } });

    expect(res.status).toBe(200);
    expect(res.body).toEqual({ result: 15 });
  });

  // --- validation errors ----------------------------------------------------

  test("returns 400 when `rule` is missing", async () => {
    const res = await request(app)
      .post("/check")
      .send({ context: { amount: 50 } });

    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/rule/i);
  });

  test("returns 400 when `rule` is an empty string", async () => {
    const res = await request(app)
      .post("/check")
      .send({ rule: "   ", context: { amount: 50 } });

    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/rule/i);
  });

  test("returns 400 when `context` is missing", async () => {
    const res = await request(app)
      .post("/check")
      .send({ rule: "amount > 100" });

    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/context/i);
  });

  test("returns 400 when `context` is an array", async () => {
    const res = await request(app)
      .post("/check")
      .send({ rule: "amount > 100", context: [1, 2, 3] });

    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/context/i);
  });

  test("returns 400 for a syntactically invalid rule", async () => {
    const res = await request(app)
      .post("/check")
      .send({ rule: "amount >>< 100", context: { amount: 50 } });

    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/invalid rule/i);
  });

  // --- security: injection attempts must NOT execute system calls -----------

  test("rejects an attempt to call require() via the rule string", async () => {
    const res = await request(app)
      .post("/check")
      .send({
        rule: "require('child_process').execSync('id')",
        context: {},
      });

    // Must not return 200; expr-eval will throw a parse/eval error
    expect(res.status).toBe(400);
  });

  test("rejects an attempt to access process.env via the rule string", async () => {
    const res = await request(app)
      .post("/check")
      .send({
        rule: "process.env.SECRET",
        context: {},
      });

    expect(res.status).toBe(400);
  });
});

