'use strict';

const express = require('express');
const vm = require('vm');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
// ---------------------------------------------------------------------------
// The RULES_ENGINE.md reference uses:
//
//   Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req)
//
// That pattern executes arbitrary caller-supplied JavaScript in the main
// process with full access to the Node.js runtime — a critical Remote Code
// Execution (RCE) vulnerability.  An attacker can supply a rule such as:
//
//   "process.env"              → leaks all environment variables / secrets
//   "require('child_process').execSync('curl …')"  → OS command injection
//   "(()=>{ while(1){} })()"   → denial of service
//   "global.hijacked = true"   → persistent global-state tampering
//
// We do NOT follow that reference.  Instead we use two defence-in-depth
// layers that together prevent code injection while still supporting the
// full set of legitimate rule expressions (comparisons, logic, arithmetic,
// string/array member access, ternaries, etc.).
//
// Layer 1 – Static blocklist
//   Reject any expression string that references dangerous globals or syntax
//   before we attempt to run it.  Covers the most common escape vectors.
//
// Layer 2 – Isolated vm sandbox
//   Execute the expression inside vm.runInNewContext() with a sandbox whose
//   prototype is Object.create(null), containing ONLY the caller-supplied
//   `ctx` value.  The sandbox has no reference to `process`, `require`,
//   `global`, `globalThis`, `Function`, `eval`, or any other Node.js
//   built-in, so even if the blocklist somehow missed a pattern, those
//   identifiers simply do not exist in the expression's scope.
// ---------------------------------------------------------------------------

/**
 * Identifiers / patterns that must never appear in a rule expression.
 * The list is intentionally conservative — legitimate business rules
 * (amount > 100, user.role === 'admin', etc.) never need these.
 */
const BLOCKED_PATTERNS = [
  /\bprocess\b/,
  /\brequire\b/,
  /\bimport\b/,
  /\bglobal\b/,
  /\bglobalThis\b/,
  /\beval\b/,
  /\bFunction\b/,
  /\bsetTimeout\b/,
  /\bsetInterval\b/,
  /\bsetImmediate\b/,
  /\bqueueMicrotask\b/,
  /\bPromise\b/,
  /\bProxy\b/,
  /\bReflect\b/,
  /\bSymbol\b/,
  /\b__proto__\b/,
  /\bprototype\b/,
  /\bconstructor\b/,
  /\bObject\s*\[/,       // Object['keys'] style access
  /\bBuffer\b/,
  /\bAtomics\b/,
  /\bSharedArrayBuffer\b/,
  /\bWebAssembly\b/,
  /\bthis\b/,
  /`/,                   // template literals can embed expressions
  /\bwith\b/,
];

/**
 * Validate a rule expression string against the static blocklist.
 * Throws an Error (caught by the /check handler) if any pattern matches.
 *
 * @param {string} expr
 */
function assertExpressionSafe(expr) {
  for (const pattern of BLOCKED_PATTERNS) {
    if (pattern.test(expr)) {
      throw new Error(`Rule expression contains a forbidden pattern: ${pattern}`);
    }
  }
}

/**
 * Evaluate a rule expression safely.
 *
 * @param {string} expr   - The rule string, e.g. 'ctx.amount > 100'
 * @param {unknown} ctx   - The context object supplied by the caller
 * @returns {boolean}     - Result of evaluating the expression
 */
function evalRule(expr, ctx) {
  // --- Layer 1: static blocklist ---
  assertExpressionSafe(expr);

  // --- Layer 2: isolated vm sandbox ---
  //
  // Object.create(null) gives us a prototype-less object, so there is no
  // path through __proto__ / constructor to escape to the real global.
  // We also deep-freeze ctx to prevent the expression from mutating the
  // caller's data.
  const sandbox = Object.create(null);
  sandbox.ctx = deepFreeze(structuredClone(ctx ?? {}));

  // vm.Script.runInContext enforces a separate V8 context — all global
  // bindings (process, require, …) are simply absent.  We also cap wall-
  // clock time with a timeout so a busy-loop rule cannot stall the server.
  const TIMEOUT_MS = 100;

  let result;
  try {
    result = vm.runInNewContext(`(${expr})`, sandbox, { timeout: TIMEOUT_MS });
  } catch (err) {
    // Re-throw with a cleaner message so we don't leak internal stack frames.
    if (err.constructor && err.constructor.name === 'Error' && /Script execution timed out/.test(err.message)) {
      throw new Error('Rule expression timed out during evaluation');
    }
    throw new Error(`Rule expression evaluation failed: ${err.message}`);
  }

  return result;
}

/** Recursively freeze an object so the vm sandbox cannot mutate caller data. */
function deepFreeze(obj) {
  if (obj === null || typeof obj !== 'object') return obj;
  Object.keys(obj).forEach((key) => deepFreeze(obj[key]));
  return Object.freeze(obj);
}

// ---------------------------------------------------------------------------
// POST /check
// ---------------------------------------------------------------------------
app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  // --- Input validation ---
  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({
      error: 'Bad Request',
      message: '"rule" must be a non-empty string',
    });
  }

  let result;
  try {
    result = evalRule(rule.trim(), context);
  } catch (err) {
    // Distinguish security rejections (forbidden pattern → 400) from
    // unexpected runtime errors (→ 500).
    const isBadInput =
      err.message.startsWith('Rule expression contains a forbidden pattern') ||
      err.message.startsWith('Rule expression evaluation failed');

    return res.status(isBadInput ? 400 : 500).json({
      error: isBadInput ? 'Bad Request' : 'Internal Server Error',
      message: err.message,
    });
  }

  return res.status(200).json({ result: Boolean(result) });
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------
const PORT = process.env.PORT ?? 3000;
app.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});

module.exports = app; // exported for testing

