"use strict";

const express = require("express");
const app = express();
app.use(express.json());

// ─── Declarative rule evaluator ──────────────────────────────────────────────

/**
 * Supported operators.
 * Extend this map to add new comparisons; never execute caller-supplied code.
 */
const OPERATORS = {
  "==": (a, b) => a == b, // loose equality (intentional – mirrors JS rule semantics)
  "===": (a, b) => a === b,
  "!=": (a, b) => a != b,
  "!==": (a, b) => a !== b,
  ">": (a, b) => a > b,
  ">=": (a, b) => a >= b,
  "<": (a, b) => a < b,
  "<=": (a, b) => a <= b,
  in: (a, b) => Array.isArray(b) && b.includes(a),
  "not-in": (a, b) => Array.isArray(b) && !b.includes(a),
  contains: (a, b) => typeof a === "string" && a.includes(String(b)),
  "starts-with": (a, b) => typeof a === "string" && a.startsWith(String(b)),
  "ends-with": (a, b) => typeof a === "string" && a.endsWith(String(b)),
};

/**
 * Resolve a dot-separated path (e.g. "user.age") against an object.
 * Returns `undefined` when any segment is absent.
 */
function resolvePath(obj, path) {
  return String(path)
    .split(".")
    .reduce((cur, key) => (cur != null ? cur[key] : undefined), obj);
}

/**
 * Evaluate a single rule object against ctx.
 *
 * Rule schema (all fields required):
 *   { "field": <string>, "op": <operator>, "value": <any> }
 *
 * Composite rules (optional):
 *   { "all": [ <rule>, ... ] }   – every sub-rule must pass
 *   { "any": [ <rule>, ... ] }   – at least one sub-rule must pass
 *   { "none": [ <rule>, ... ] }  – no sub-rule must pass
 *
 * @param {object} rule  - Parsed rule object.
 * @param {object} ctx   - Caller-supplied context (req.body.context).
 * @returns {boolean}
 * @throws {Error} when the rule object is malformed or the operator is unknown.
 */
function evalRule(rule, ctx) {
  if (rule == null || typeof rule !== "object") {
    throw new Error("Each rule must be a non-null object.");
  }

  // ── Composite: all / any / none ──────────────────────────────────────────
  if ("all" in rule) {
    if (!Array.isArray(rule.all) || rule.all.length === 0) {
      throw new Error('"all" must be a non-empty array of rules.');
    }
    return rule.all.every((r) => evalRule(r, ctx));
  }

  if ("any" in rule) {
    if (!Array.isArray(rule.any) || rule.any.length === 0) {
      throw new Error('"any" must be a non-empty array of rules.');
    }
    return rule.any.some((r) => evalRule(r, ctx));
  }

  if ("none" in rule) {
    if (!Array.isArray(rule.none) || rule.none.length === 0) {
      throw new Error('"none" must be a non-empty array of rules.');
    }
    return !rule.none.some((r) => evalRule(r, ctx));
  }

  // ── Leaf rule ────────────────────────────────────────────────────────────
  const { field, op, value } = rule;

  if (typeof field !== "string" || field.trim() === "") {
    throw new Error('"field" must be a non-empty string.');
  }
  if (typeof op !== "string" || !(op in OPERATORS)) {
    throw new Error(
      `Unknown operator "${op}". Supported: ${Object.keys(OPERATORS).join(", ")}.`
    );
  }
  if (value === undefined) {
    throw new Error('"value" is required.');
  }

  const actual = resolvePath(ctx, field);
  return OPERATORS[op](actual, value);
}

// ─── POST /check ─────────────────────────────────────────────────────────────

/**
 * POST /check
 *
 * Request body (JSON):
 * {
 *   "rule":    { "field": "amount", "op": ">", "value": 100 },
 *   "context": { "amount": 250, ... }
 * }
 *
 * Success response 200:
 * { "result": true | false }
 *
 * Error response 400:
 * { "error": "<reason>" }
 */
app.post("/check", (req, res) => {
  const { rule, context } = req.body ?? {};

  if (rule === undefined) {
    return res.status(400).json({ error: '"rule" is required.' });
  }
  if (context === undefined || typeof context !== "object" || context === null) {
    return res.status(400).json({ error: '"context" must be a non-null object.' });
  }

  let result;
  try {
    result = evalRule(rule, context);
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }

  return res.status(200).json({ result: Boolean(result) });
});

// ─── Start ───────────────────────────────────────────────────────────────────

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`acme-rules listening on port ${PORT}`);
});

module.exports = app; // exported for testing

