// ---------------------------------------------------------------------------
// Safe rule evaluator
//
// NOTE: docs/RULES_ENGINE.md proposes using new Function() / eval() to execute
// caller-supplied rule strings. That would allow any caller to run arbitrary
// code on the server (RCE). The implementation below achieves the same goal —
// evaluating a rule expression against a context object — without any dynamic
// code execution.
//
// Supported grammar (recursive):
//
//   expr   = comparison | logical
//   logical    = expr ('&&' | '||') expr
//   comparison = field OP value
//   field      = 'ctx.' <identifier>  (dot-path into the context object)
//   OP         = '===' | '!==' | '>=' | '<=' | '>' | '<'
//   value      = number | boolean | single-quoted string | double-quoted string
//
// Examples:
//   "ctx.amount > 100"
//   "ctx.role === 'admin'"
//   "ctx.active === true && ctx.score >= 50"
// ---------------------------------------------------------------------------

const COMPARISON_RE =
  /^\s*(ctx(?:\.[A-Za-z_]\w*)+)\s*(===|!==|>=|<=|>|<)\s*(-?\d+(?:\.\d+)?|true|false|'[^']*'|"[^"]*")\s*$/;

/**
 * Resolve a dot-path like "ctx.foo.bar" against { ctx }.
 * Returns undefined if any segment is missing.
 */
function resolvePath(path, vars) {
  return path.split('.').reduce((obj, key) => {
    if (obj === undefined || obj === null) return undefined;
    return obj[key];
  }, vars);
}

/**
 * Parse a literal token from the rule string into its JS value.
 */
function parseLiteral(raw) {
  const trimmed = raw.trim();
  if (trimmed === 'true') return true;
  if (trimmed === 'false') return false;
  if (/^-?\d+(\.\d+)?$/.test(trimmed)) return Number(trimmed);
  // quoted string — strip surrounding quotes
  if (
    (trimmed.startsWith("'") && trimmed.endsWith("'")) ||
    (trimmed.startsWith('"') && trimmed.endsWith('"'))
  ) {
    return trimmed.slice(1, -1);
  }
  throw new Error(`Unsupported literal: ${raw}`);
}

/**
 * Evaluate a single comparison clause against the provided vars object.
