/**
 * app.js — acme-rules Dynamic Rule Engine
 *
 * POST /check
 *   Body: { rule: string, context: object }
 *   Response 200: { result: boolean }
 *   Response 400: { error: string }
 *
 * Zero external dependencies — uses only Node.js built-ins.
 *
 * SECURITY NOTE
 * -------------
 * The reference implementation in docs/RULES_ENGINE.md uses new Function() /
 * eval() to execute caller-supplied strings.  That is Remote Code Execution
 * (RCE): any caller can run arbitrary OS commands, read secrets, exfiltrate
 * data, or crash the process.  This implementation intentionally replaces that
 * approach with a fully sandboxed evaluator that:
 *
 *   1. Tokenises the rule string with a hand-written lexer.
 *   2. Parses the token stream into an AST with a recursive-descent parser.
 *   3. Walks the AST with an interpreter — no eval(), no new Function().
 *   4. Whitelists every AST node type; anything outside the whitelist throws.
 *
 * Supported rule syntax
 * ---------------------
 *   Literals    : numbers (42, 3.14), strings ('hi', "hi"), true, false, null
 *   Identifiers : ctx  (bound to req.body.context)
 *   Member acc. : ctx.amount, ctx.user.role  (dot notation only)
 *   Arithmetic  : +  -  *  /  %
 *   Comparison  : ==  !=  <  <=  >  >=
 *   Logical     : &&  ||  !
 *   Grouping    : ( expr )
 *
 * Examples
 *   ctx.amount > 100
 *   ctx.user.role == 'admin' && ctx.score >= 90
 *   !(ctx.blocked) && ctx.level < 5
 */

'use strict';

const http = require('node:http');

// ─── Lexer ────────────────────────────────────────────────────────────────────

const TT = Object.freeze({
  NUMBER: 'NUMBER', STRING: 'STRING',
  IDENT:  'IDENT',  DOT:    'DOT',
  PLUS:   'PLUS',   MINUS:  'MINUS', STAR:  'STAR', SLASH: 'SLASH', PCT: 'PCT',
  EQ:     'EQ',     NEQ:    'NEQ',
  LT:     'LT',     LTE:    'LTE',   GT:    'GT',   GTE:   'GTE',
  AND:    'AND',    OR:     'OR',    BANG:  'BANG',
  LPAREN: 'LPAREN', RPAREN: 'RPAREN',
  EOF:    'EOF',
});

function tokenise(src) {
  const tokens = [];
  let i = 0;

  while (i < src.length) {
    // Whitespace
    if (/\s/.test(src[i])) { i++; continue; }

    // Numbers (integer or decimal)
    if (/[0-9]/.test(src[i])) {
      let raw = '';
      while (i < src.length && /[0-9.]/.test(src[i])) raw += src[i++];
      tokens.push({ type: TT.NUMBER, value: parseFloat(raw) });
      continue;
    }

    // Quoted strings  'abc'  or  "abc"
    if (src[i] === "'" || src[i] === '"') {
      const quote = src[i++];
      let str = '';
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\' && i + 1 < src.length) {
          i++;
          const esc = src[i++];
          str += esc === 'n' ? '\n' : esc === 't' ? '\t' : esc;
        } else {
          str += src[i++];
        }
      }
      if (src[i] !== quote) throw new Error('Unterminated string literal');
      i++; // closing quote
      tokens.push({ type: TT.STRING, value: str });
      continue;
    }

    // Identifiers and keywords
    if (/[a-zA-Z_$]/.test(src[i])) {
      let name = '';
      while (i < src.length && /[a-zA-Z_$0-9]/.test(src[i])) name += src[i++];
      tokens.push({ type: TT.IDENT, value: name });
      continue;
    }

    // Two-character operators (must be checked before single-char)
    const two = src.slice(i, i + 2);
    if (two === '==') { tokens.push({ type: TT.EQ  }); i += 2; continue; }
    if (two === '!=') { tokens.push({ type: TT.NEQ }); i += 2; continue; }
    if (two === '<=') { tokens.push({ type: TT.LTE }); i += 2; continue; }
    if (two === '>=') { tokens.push({ type: TT.GTE }); i += 2; continue; }
    if (two === '&&') { tokens.push({ type: TT.AND }); i += 2; continue; }
    if (two === '||') { tokens.push({ type: TT.OR  }); i += 2; continue; }

    // Single-character operators
    switch (src[i]) {
      case '<': tokens.push({ type: TT.LT    }); i++; continue;
      case '>': tokens.push({ type: TT.GT    }); i++; continue;
      case '!': tokens.push({ type: TT.BANG  }); i++; continue;
      case '+': tokens.push({ type: TT.PLUS  }); i++; continue;
      case '-': tokens.push({ type: TT.MINUS }); i++; continue;
      case '*': tokens.push({ type: TT.STAR  }); i++; continue;
      case '/': tokens.push({ type: TT.SLASH }); i++; continue;
      case '%': tokens.push({ type: TT.PCT   }); i++; continue;
      case '.': tokens.push({ type: TT.DOT   }); i++; continue;
      case '(': tokens.push({ type: TT.LPAREN}); i++; continue;
      case ')': tokens.push({ type: TT.RPAREN}); i++; continue;
      default:
        throw new Error(`Unexpected character '${src[i]}' at position ${i}`);
    }
  }

  tokens.push({ type: TT.EOF });
  return tokens;
}

// ─── Parser (recursive descent) ──────────────────────────────────────────────
//
// Grammar (lowest → highest precedence):
//
//   expr       → or
//   or         → and  ( '||' and )*
//   and        → equality  ( '&&' equality )*
//   equality   → comparison  ( ( '==' | '!=' ) comparison )*
//   comparison → addition  ( ( '<' | '<=' | '>' | '>=' ) addition )*
//   addition   → mult  ( ( '+' | '-' ) mult )*
//   mult       → unary  ( ( '*' | '/' | '%' ) unary )*
//   unary      → '!' unary | '-' unary | member
//   member     → primary ( '.' IDENT )*
//   primary    → NUMBER | STRING | 'true' | 'false' | 'null'
//               | IDENT | '(' expr ')'

function parse(tokens) {
  let pos = 0;

  const peek    = ()      => tokens[pos];
  const advance = ()      => tokens[pos++];
  const check   = (t)     => peek().type === t;
  const match   = (...ts) => ts.includes(peek().type) ? advance() : null;

  function expect(type) {
    if (!check(type)) {
      throw new Error(`Expected ${type} but got ${peek().type}`);
    }
    return advance();
  }

  // Each parse* function returns an AST node.

  function parseExpr()       { return parseOr(); }

  function parseOr() {
    let node = parseAnd();
    while (check(TT.OR)) {
      const op = advance().type;
      node = { type: 'Binary', op, left: node, right: parseAnd() };
    }
    return node;
  }

  function parseAnd() {
    let node = parseEquality();
    while (check(TT.AND)) {
      const op = advance().type;
      node = { type: 'Binary', op, left: node, right: parseEquality() };
    }
    return node;
  }

  function parseEquality() {
    let node = parseComparison();
    while (check(TT.EQ) || check(TT.NEQ)) {
      const op = advance().type;
      node = { type: 'Binary', op, left: node, right: parseComparison() };
    }
    return node;
  }

  function parseComparison() {
    let node = parseAddition();
    while ([TT.LT, TT.LTE, TT.GT, TT.GTE].includes(peek().type)) {
      const op = advance().type;
      node = { type: 'Binary', op, left: node, right: parseAddition() };
    }
    return node;
  }

  function parseAddition() {
    let node = parseMult();
    while (check(TT.PLUS) || check(TT.MINUS)) {
      const op = advance().type;
      node = { type: 'Binary', op, left: node, right: parseMult() };
    }
    return node;
  }

  function parseMult() {
    let node = parseUnary();
    while ([TT.STAR, TT.SLASH, TT.PCT].includes(peek().type)) {
      const op = advance().type;
      node = { type: 'Binary', op, left: node, right: parseUnary() };
    }
    return node;
  }

  function parseUnary() {
    if (check(TT.BANG)) {
      advance();
      return { type: 'Unary', op: TT.BANG, operand: parseUnary() };
    }
    if (check(TT.MINUS)) {
      advance();
      return { type: 'Unary', op: TT.MINUS, operand: parseUnary() };
    }
    return parseMember();
  }

  function parseMember() {
    let node = parsePrimary();
    while (check(TT.DOT)) {
      advance();                        // consume '.'
      const prop = expect(TT.IDENT);
      node = { type: 'Member', object: node, property: prop.value };
    }
    return node;
  }

  function parsePrimary() {
    const tok = peek();

    if (tok.type === TT.NUMBER) { advance(); return { type: 'Literal', value: tok.value }; }
    if (tok.type === TT.STRING) { advance(); return { type: 'Literal', value: tok.value }; }

    if (tok.type === TT.IDENT) {
      advance();
      // Keyword literals
      if (tok.value === 'true')  return { type: 'Literal', value: true  };
      if (tok.value === 'false') return { type: 'Literal', value: false };
      if (tok.value === 'null')  return { type: 'Literal', value: null  };
      // Only 'ctx' is a valid root identifier — anything else is rejected
      if (tok.value !== 'ctx') {
        throw new Error(
          `Identifier '${tok.value}' is not allowed. Only 'ctx' is a valid root identifier.`
        );
      }
      return { type: 'Identifier', name: 'ctx' };
    }

    if (tok.type === TT.LPAREN) {
      advance();
      const node = parseExpr();
      expect(TT.RPAREN);
      return node;
    }

    throw new Error(`Unexpected token '${tok.type}' in expression`);
  }

  const ast = parseExpr();
  if (!check(TT.EOF)) {
    throw new Error(`Unexpected token '${peek().type}' after end of expression`);
  }
  return ast;
}

// ─── Interpreter ─────────────────────────────────────────────────────────────

function evaluate(node, ctx) {
  switch (node.type) {

    case 'Literal':
      return node.value;

    case 'Identifier':
      // Parser enforces name === 'ctx'
      return ctx;

    case 'Member': {
      const obj = evaluate(node.object, ctx);
      if (obj === null || obj === undefined) return undefined;
      if (typeof obj !== 'object') {
        throw new Error(
          `Cannot read property '${node.property}' of a non-object value`
        );
      }
      // Use hasOwnProperty to prevent prototype-chain access (__proto__, etc.)
      if (!Object.prototype.hasOwnProperty.call(obj, node.property)) {
        return undefined;
      }
      return obj[node.property];
    }

    case 'Unary': {
      const val = evaluate(node.operand, ctx);
      if (node.op === TT.BANG)  return !val;
      if (node.op === TT.MINUS) return -val;
      throw new Error(`Unknown unary operator '${node.op}'`);
    }

    case 'Binary': {
      // Short-circuit logical operators before evaluating RHS
      if (node.op === TT.AND) {
        return evaluate(node.left, ctx) && evaluate(node.right, ctx);
      }
      if (node.op === TT.OR) {
        return evaluate(node.left, ctx) || evaluate(node.right, ctx);
      }

      const l = evaluate(node.left,  ctx);
      const r = evaluate(node.right, ctx);

      switch (node.op) {
        case TT.EQ:    return l == r;    // loose equality mirrors typical rule semantics
        case TT.NEQ:   return l != r;
        case TT.LT:    return l <  r;
        case TT.LTE:   return l <= r;
        case TT.GT:    return l >  r;
        case TT.GTE:   return l >= r;
        case TT.PLUS:  return l +  r;
        case TT.MINUS: return l -  r;
        case TT.STAR:  return l *  r;
        case TT.SLASH: return l /  r;
        case TT.PCT:   return l %  r;
        default:
          throw new Error(`Unknown binary operator '${node.op}'`);
      }
    }

    default:
      throw new Error(`Unsupported AST node type '${node.type}'`);
  }
}

// ─── Public API ──────────────────────────────────────────────────────────────

/**
 * Safely evaluates a rule expression string against a context object.
 *
 * @param {string} rule    - The rule expression, e.g. 'ctx.amount > 100'
 * @param {object} context - The context object bound to `ctx` in the rule
 * @returns {boolean}      - Result of the evaluated rule
 * @throws  {Error}        - If the rule is syntactically or semantically invalid
 */
function evalRule(rule, context) {
  if (typeof rule !== 'string' || rule.trim() === '') {
    throw new Error("'rule' must be a non-empty string");
  }
  const tokens = tokenise(rule);
  const ast    = parse(tokens);
  const result = evaluate(ast, context);
  return result;
}

// ─── HTTP helpers ─────────────────────────────────────────────────────────────

function readBody(req) {
  return new Promise((resolve, reject) => {
    let raw = '';
    req.on('data', chunk => { raw += chunk; });
    req.on('end',  ()    => {
      try { resolve(JSON.parse(raw || 'null')); }
      catch { reject(new Error('Request body is not valid JSON')); }
    });
    req.on('error', reject);
  });
}

function sendJSON(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type':   'application/json',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

// ─── POST /check handler ─────────────────────────────────────────────────────

async function handleCheck(req, res) {
  let parsed;
  try {
    parsed = await readBody(req);
  } catch (err) {
    return sendJSON(res, 400, { error: err.message });
  }

  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return sendJSON(res, 400, { error: 'Request body must be a JSON object' });
  }

  const { rule, context } = parsed;

  if (typeof rule !== 'string' || rule.trim() === '') {
    return sendJSON(res, 400, { error: "'rule' must be a non-empty string" });
  }
  if (context === undefined || context === null || typeof context !== 'object' || Array.isArray(context)) {
    return sendJSON(res, 400, { error: "'context' must be a JSON object" });
  }

  let result;
  try {
    result = evalRule(rule, context);
  } catch (err) {
    return sendJSON(res, 400, { error: err.message });
  }

  return sendJSON(res, 200, { result: !!result });
}

// ─── HTTP server ─────────────────────────────────────────────────────────────

const server = http.createServer(async (req, res) => {
  if (req.method === 'POST' && req.url === '/check') {
    try {
      await handleCheck(req, res);
    } catch (err) {
      // Catch unexpected errors so the server doesn't crash
      sendJSON(res, 500, { error: 'Internal server error' });
    }
    return;
  }
  sendJSON(res, 404, { error: 'Not found' });
});

// ─── Start ────────────────────────────────────────────────────────────────────

const PORT = process.env.PORT || 3000;
if (require.main === module) {
  server.listen(PORT, () => {
    console.log(`acme-rules listening on port ${PORT}`);
  });
}

module.exports = { server, evalRule }; // export for testing

/**
 * app.test.js — tests for POST /check and the evalRule engine
 *
 * Run with:  node --test app.test.js
 * (requires Node >= 18 for node:test)
 */

'use strict';

const { describe, it, before, after } = require('node:test');
const assert = require('node:assert/strict');
const http   = require('node:http');

const { server, evalRule } = require('./app');

// ─── Boot the server on a random free port ────────────────────────────────────

before(async () => {
  server.listen(0);
  await new Promise(r => server.once('listening', r));
});

after(async () => {
  await new Promise(r => server.close(r));
});

// ─── HTTP helper ─────────────────────────────────────────────────────────────

function post(payload) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(payload);
    const { port } = server.address();
    const req = http.request(
      {
        hostname: '127.0.0.1', port,
        path: '/check', method: 'POST',
        headers: {
          'Content-Type':   'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (res) => {
        let data = '';
        res.on('data',  chunk => { data += chunk; });
        res.on('end',   ()    => resolve({ status: res.statusCode, body: JSON.parse(data) }));
      }
    );
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

// ═════════════════════════════════════════════════════════════════════════════
// Unit tests — evalRule()
// ═════════════════════════════════════════════════════════════════════════════

describe('evalRule() — comparison operators', () => {
  it('> true',  () => assert.equal(evalRule('ctx.amount > 100',  { amount: 150 }), true));
  it('> false', () => assert.equal(evalRule('ctx.amount > 100',  { amount:  50 }), false));
  it('>=',      () => assert.equal(evalRule('ctx.score >= 90',   { score:   90 }), true));
  it('<=',      () => assert.equal(evalRule('ctx.score <= 10',   { score:   10 }), true));
  it('<',       () => assert.equal(evalRule('ctx.x < 0',         { x:       -1 }), true));
});

describe('evalRule() — equality operators', () => {
  it("== string",  () => assert.equal(evalRule("ctx.role == 'admin'", { role: 'admin' }), true));
  it("!= string",  () => assert.equal(evalRule("ctx.role != 'admin'", { role: 'user'  }), true));
  it("== boolean", () => assert.equal(evalRule('ctx.enabled == true', { enabled: true }), true));
  it("== null",    () => assert.equal(evalRule('ctx.x == null',       { x: null       }), true));
});

describe('evalRule() — logical operators', () => {
  it('&&  both true',         () => assert.equal(evalRule("ctx.role == 'admin' && ctx.score >= 90", { role: 'admin', score: 95 }), true));
  it('&&  second false',      () => assert.equal(evalRule("ctx.role == 'admin' && ctx.score >= 90", { role: 'admin', score: 70 }), false));
  it('||  one true',          () => assert.equal(evalRule('ctx.a > 10 || ctx.b > 10', { a: 5, b: 20 }), true));
  it('||  both false',        () => assert.equal(evalRule('ctx.a > 10 || ctx.b > 10', { a: 1, b:  2 }), false));
  it('!   negates false',     () => assert.equal(evalRule('!(ctx.blocked)',            { blocked: false }), true));
  it('!   negates true',      () => assert.equal(evalRule('!(ctx.blocked)',            { blocked: true  }), false));
  it('&&  short-circuits LHS false', () => assert.equal(evalRule('ctx.flag && ctx.score > 0', { flag: false, score: 100 }), false));
});

describe('evalRule() — arithmetic', () => {
  it('+', () => assert.equal(evalRule('ctx.a + ctx.b > 10', { a: 7,  b: 5  }), true));
  it('-', () => assert.equal(evalRule('ctx.a - ctx.b < 50', { a: 80, b: 35 }), true));
  it('*', () => assert.equal(evalRule('ctx.x * 2 == 20',    { x: 10        }), true));
  it('/', () => assert.equal(evalRule('ctx.x / 4 == 5',     { x: 20        }), true));
  it('%', () => assert.equal(evalRule('ctx.x % 2 == 0',     { x: 4         }), true));
});

describe('evalRule() — literals', () => {
  it('integer literal',  () => assert.equal(evalRule('ctx.x > 0',  { x: 1   }), true));
  it('decimal literal',  () => assert.equal(evalRule('ctx.x > 0.5',{ x: 0.9 }), true));
  it('string literal',   () => assert.equal(evalRule("ctx.s == 'hello'", { s: 'hello' }), true));
  it('true literal',     () => assert.equal(evalRule('ctx.v == true',  { v: true  }), true));
  it('false literal',    () => assert.equal(evalRule('ctx.v == false', { v: false }), true));
  it('null literal',     () => assert.equal(evalRule('ctx.v == null',  { v: null  }), true));
});

describe('evalRule() — nested property access', () => {
  it('two levels deep',   () => assert.equal(evalRule("ctx.user.role == 'admin'", { user: { role: 'admin' } }), true));
  it('three levels deep', () => assert.equal(evalRule('ctx.a.b.c > 1',            { a: { b: { c: 5 } } }), true));
  it('missing path → undefined == null (loose)', () =>
    assert.equal(evalRule('ctx.user.role == null', { user: {} }), true)  // undefined == null
  );
  it('missing top-level key → undefined == null', () =>
    assert.equal(evalRule('ctx.missing == null', {}), true)
  );
});

describe('evalRule() — grouping & precedence', () => {
  it('parentheses override precedence', () =>
    assert.equal(evalRule('(ctx.a + ctx.b) * 2 > 10', { a: 3, b: 3 }), true)
  );
  it('&& binds tighter than ||', () =>
    // true || (false && false) → true
    assert.equal(evalRule('ctx.x > 0 || ctx.y > 0 && ctx.z > 0', { x: 1, y: 0, z: 0 }), true)
  );
  it('unary minus', () =>
    assert.equal(evalRule('-ctx.x < 0', { x: 5 }), true)
  );
});

describe('evalRule() — error cases', () => {
  it('empty rule throws',           () => assert.throws(() => evalRule('', {})));
  it('whitespace-only rule throws', () => assert.throws(() => evalRule('  ', {})));
  it('bare unknown identifier',     () => assert.throws(() => evalRule('process.env', {})));
  it('unknown root identifier',     () => assert.throws(() => evalRule('foo.bar > 1', {})));
  it('unclosed paren',              () => assert.throws(() => evalRule('(ctx.x > 1',  { x: 2 })));
  it('trailing garbage',            () => assert.throws(() => evalRule('ctx.x > 1 !!',{ x: 2 })));
  it('empty expression in parens',  () => assert.throws(() => evalRule('()', {})));
});

describe('evalRule() — security: injection attempts all throw', () => {
  const cases = [
    "process.exit(1)",
    "require('fs')",
    "eval('1+1')",
    "global.x",
    "__proto__.x",
    "constructor.x",
  ];
  for (const rule of cases) {
    it(`rejects: ${rule}`, () => assert.throws(() => evalRule(rule, {})));
  }
});

// ═════════════════════════════════════════════════════════════════════════════
// Integration tests — POST /check (HTTP layer)
// ═════════════════════════════════════════════════════════════════════════════

describe('POST /check — 200 success cases', () => {
  it('basic comparison true',  async () => {
    const r = await post({ rule: 'ctx.amount > 100', context: { amount: 150 } });
    assert.equal(r.status, 200);
    assert.equal(r.body.result, true);
  });

  it('basic comparison false', async () => {
    const r = await post({ rule: 'ctx.amount > 100', context: { amount: 50 } });
    assert.equal(r.status, 200);
    assert.equal(r.body.result, false);
  });

  it('nested property', async () => {
    const r = await post({ rule: "ctx.user.role == 'admin'", context: { user: { role: 'admin' } } });
    assert.equal(r.status, 200);
    assert.equal(r.body.result, true);
  });

  it('compound logical expression', async () => {
    const r = await post({
      rule:    "ctx.role == 'admin' && ctx.score >= 90",
      context: { role: 'admin', score: 95 },
    });
    assert.equal(r.status, 200);
    assert.equal(r.body.result, true);
  });

  it('result is always a boolean', async () => {
    const r = await post({ rule: 'ctx.x > 0', context: { x: 1 } });
    assert.equal(r.status, 200);
    assert.equal(typeof r.body.result, 'boolean');
  });
});

describe('POST /check — 400 validation: missing / bad inputs', () => {
  it('missing rule → 400',             async () => assert.equal((await post({ context: {} })).status, 400));
  it('null rule → 400',                async () => assert.equal((await post({ rule: null,  context: {} })).status, 400));
  it('empty rule → 400',               async () => assert.equal((await post({ rule: '',    context: {} })).status, 400));
  it('whitespace rule → 400',          async () => assert.equal((await post({ rule: '  ',  context: {} })).status, 400));
  it('missing context → 400',          async () => assert.equal((await post({ rule: 'ctx.x > 0' })).status, 400));
  it('null context → 400',             async () => assert.equal((await post({ rule: 'ctx.x > 0', context: null })).status, 400));
  it('array context → 400',            async () => assert.equal((await post({ rule: 'ctx.x > 0', context: [] })).status, 400));
  it('string context → 400',           async () => assert.equal((await post({ rule: 'ctx.x > 0', context: 'bad' })).status, 400));
  it('syntax error in rule → 400',     async () => assert.equal((await post({ rule: 'ctx.x >',    context: { x: 1 } })).status, 400));
  it('bad identifier in rule → 400',   async () => assert.equal((await post({ rule: 'process.env', context: {} })).status, 400));
  it('response body has error field',  async () => {
    const r = await post({ rule: 'ctx.x >', context: { x: 1 } });
    assert.equal(r.status, 400);
    assert.ok(typeof r.body.error === 'string' && r.body.error.length > 0);
  });
});

describe('POST /check — 400 security: injection attempts', () => {
  const attacks = [
    { rule: "process.exit(1)",          context: {} },
    { rule: "require('fs')",            context: {} },
    { rule: "eval('1')",                context: {} },
    { rule: "global.process",           context: {} },
  ];
  for (const payload of attacks) {
    it(`blocks: ${payload.rule}`, async () => {
      const r = await post(payload);
      assert.equal(r.status, 400);
    });
  }

  it('server still responds correctly after all attacks', async () => {
    const r = await post({ rule: 'ctx.ok == true', context: { ok: true } });
    assert.equal(r.status, 200);
    assert.equal(r.body.result, true);
  });
});

describe('POST /check — 404 for unknown routes', () => {
  it('GET /check → 404', async () => {
    const { port } = server.address();
    const r = await new Promise((resolve, reject) => {
      http.get(`http://127.0.0.1:${port}/check`, (res) => {
        let d = '';
        res.on('data', c => d += c);
        res.on('end', () => resolve({ status: res.statusCode, body: JSON.parse(d) }));
      }).on('error', reject);
    });
    assert.equal(r.status, 404);
  });
});

