const express = require('express');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
// ---------------------------------------------------------------------------
// The reference implementation in docs/RULES_ENGINE.md proposes using the
// Function constructor to evaluate caller-supplied rule strings. That approach
// is Remote Code Execution (RCE): any client can run arbitrary code inside the
// server process (read files, exfiltrate env vars, crash the process, etc.).
//
// This implementation provides an equivalent feature set — evaluating boolean
// expressions over a "ctx" object — using a strict allowlist of operators and
// operand types, with no access to the JS runtime.
// ---------------------------------------------------------------------------

/**
 * Supported binary operators and their implementations.
 * Only pure value-comparison / logical operations are allowed.
 */
const BINARY_OPS = {
  '>'  : (a, b) => a >   b,
  '>=' : (a, b) => a >=  b,
  '<'  : (a, b) => a <   b,
  '<=' : (a, b) => a <=  b,
  '==' : (a, b) => a ==  b, // eslint-disable-line eqeqeq
  '===': (a, b) => a === b,
  '!=' : (a, b) => a !=  b, // eslint-disable-line eqeqeq
  '!==': (a, b) => a !== b,
  '&&' : (a, b) => a &&  b,
  '||' : (a, b) => a ||  b,
};

// Tokeniser — returns an array of typed tokens from the rule string.
// Recognised token types:
//   { type: 'number',  value: <number>  }
//   { type: 'string',  value: <string>  }
//   { type: 'boolean', value: <boolean> }
//   { type: 'null',    value: null      }
//   { type: 'ident',   value: <string>  }  — e.g. "ctx", "amount", "ctx.amount"
//   { type: 'op',      value: <string>  }  — one of BINARY_OPS keys
//   { type: 'not',     value: '!'       }
//   { type: 'lparen',  value: '('       }
//   { type: 'rparen',  value: ')'       }
function tokenise(expr) {
  const tokens = [];
  let i = 0;

  while (i < expr.length) {
    // Skip whitespace
    if (/\s/.test(expr[i])) { i++; continue; }

    // String literals  'foo'  or  "foo"
    if (expr[i] === '"' || expr[i] === "'") {
      const quote = expr[i++];
      let str = '';
      while (i < expr.length && expr[i] !== quote) {
        if (expr[i] === '\\') { i++; } // skip escape char (basic support)
        str += expr[i++];
      }
      if (expr[i] !== quote) throw new SyntaxError('Unterminated string literal');
      i++; // closing quote
      tokens.push({ type: 'string', value: str });
      continue;
    }

    // Numbers (integer or decimal, optional leading minus handled as unary)
    if (/[0-9]/.test(expr[i]) || (expr[i] === '-' && /[0-9]/.test(expr[i + 1] || ''))) {
      let num = '';
      if (expr[i] === '-') num += expr[i++];
      while (i < expr.length && /[0-9.]/.test(expr[i])) num += expr[i++];
      tokens.push({ type: 'number', value: Number(num) });
      continue;
    }

    // Identifiers and keywords: true, false, null, ctx.*
    if (/[a-zA-Z_$]/.test(expr[i])) {
      let ident = '';
      // Consume dotted paths (e.g. ctx.user.age) as a single ident token
      while (i < expr.length && /[a-zA-Z0-9_$.]/.test(expr[i])) ident += expr[i++];
      if (ident === 'true')  { tokens.push({ type: 'boolean', value: true  }); continue; }
      if (ident === 'false') { tokens.push({ type: 'boolean', value: false }); continue; }
      if (ident === 'null')  { tokens.push({ type: 'null',    value: null  }); continue; }
      tokens.push({ type: 'ident', value: ident });
      continue;
    }

    // Multi-char operators first (order matters: check longer ones first)
    if (expr.slice(i, i + 3) === '===') { tokens.push({ type: 'op', value: '===' }); i += 3; continue; }
    if (expr.slice(i, i + 3) === '!==') { tokens.push({ type: 'op', value: '!==' }); i += 3; continue; }
    if (expr.slice(i, i + 2) === '>=')  { tokens.push({ type: 'op', value: '>='  }); i += 2; continue; }
    if (expr.slice(i, i + 2) === '<=')  { tokens.push({ type: 'op', value: '<='  }); i += 2; continue; }
    if (expr.slice(i, i + 2) === '==')  { tokens.push({ type: 'op', value: '=='  }); i += 2; continue; }
    if (expr.slice(i, i + 2) === '!=')  { tokens.push({ type: 'op', value: '!='  }); i += 2; continue; }
    if (expr.slice(i, i + 2) === '&&')  { tokens.push({ type: 'op', value: '&&'  }); i += 2; continue; }
    if (expr.slice(i, i + 2) === '||')  { tokens.push({ type: 'op', value: '||'  }); i += 2; continue; }
    if (expr[i] === '>')   { tokens.push({ type: 'op',     value: '>'  }); i++; continue; }
    if (expr[i] === '<')   { tokens.push({ type: 'op',     value: '<'  }); i++; continue; }
    if (expr[i] === '!')   { tokens.push({ type: 'not',    value: '!'  }); i++; continue; }
    if (expr[i] === '(')   { tokens.push({ type: 'lparen', value: '('  }); i++; continue; }
    if (expr[i] === ')')   { tokens.push({ type: 'rparen', value: ')'  }); i++; continue; }

    throw new SyntaxError(`Unexpected character: ${expr[i]}`);
  }

  return tokens;
}

// ---------------------------------------------------------------------------
// Recursive-descent parser + evaluator
//
// Grammar (loosely, low-to-high precedence):
//   expr   → or
//   or     → and  ( '||' and  )*
//   and    → cmp  ( '&&' cmp  )*
//   cmp    → unary ( ( '>' | '>=' | '<' | '<=' | '==' | '===' | '!=' | '!==' ) unary )?
//   unary  → '!' unary | primary
//   primary→ '(' expr ')' | literal | ident
// ---------------------------------------------------------------------------

/**
 * Resolve a dotted identifier against the context object.
 * Only "ctx" (and dotted descendants of it) is in scope.
 * Any other top-level name throws a ReferenceError.
 */
function resolveIdent(ident, ctx) {
  const parts = ident.split('.');
  if (parts[0] !== 'ctx') {
    throw new ReferenceError(
      `Identifier "${parts[0]}" is not in scope. Only "ctx" is allowed.`
    );
  }
  let value = ctx;
  for (const part of parts.slice(1)) {
    if (value === null || value === undefined) return undefined;
    value = value[part];
  }
  return value;
}

function parse(tokens, ctx) {
  let pos = 0;

  function peek()    { return tokens[pos]; }
  function consume() { return tokens[pos++]; }
  function expect(type, value) {
    const tok = consume();
    if (!tok || tok.type !== type || (value !== undefined && tok.value !== value)) {
      throw new SyntaxError(
        `Expected ${type}${value !== undefined ? ' "' + value + '"' : ''} but got ${tok ? JSON.stringify(tok) : 'end of input'}`
      );
    }
    return tok;
  }

  function parseExpr()    { return parseOr(); }

  function parseOr() {
    let left = parseAnd();
    while (peek()?.type === 'op' && peek().value === '||') {
      consume();
      const right = parseAnd();
      left = BINARY_OPS['||'](left, right);
    }
    return left;
  }

  function parseAnd() {
    let left = parseCmp();
    while (peek()?.type === 'op' && peek().value === '&&') {
      consume();
      const right = parseCmp();
      left = BINARY_OPS['&&'](left, right);
    }
    return left;
  }

  function parseCmp() {
    let left = parseUnary();
    const cmpOps = ['>', '>=', '<', '<=', '==', '===', '!=', '!=='];
    while (peek()?.type === 'op' && cmpOps.includes(peek().value)) {
      const op = consume().value;
      const right = parseUnary();
      left = BINARY_OPS[op](left, right);
    }
    return left;
  }

  function parseUnary() {
    if (peek()?.type === 'not') {
      consume();
      return !parseUnary();
    }
    return parsePrimary();
  }

  function parsePrimary() {
    const tok = peek();
    if (!tok) throw new SyntaxError('Unexpected end of expression');

    if (tok.type === 'lparen') {
      consume();
      const val = parseExpr();
      expect('rparen', ')');
      return val;
    }

    if (tok.type === 'number'  ||
        tok.type === 'string'  ||
        tok.type === 'boolean' ||
        tok.type === 'null') {
      consume();
      return tok.value;
    }

    if (tok.type === 'ident') {
      consume();
      return resolveIdent(tok.value, ctx);
    }

    throw new SyntaxError(`Unexpected token: ${JSON.stringify(tok)}`);
  }

  const result = parseExpr();

  if (pos < tokens.length) {
    throw new SyntaxError(`Unexpected token after expression: ${JSON.stringify(tokens[pos])}`);
  }

  return result;
}

/**
 * Evaluate a rule expression string against a context object.
 * Returns a boolean.
 * Throws SyntaxError / ReferenceError / TypeError on bad input.
 *
 * Supported constructs:
 *   - Numeric / string / boolean / null literals
 *   - "ctx" and dotted property paths: ctx.amount, ctx.user.role
 *   - Comparison operators:  >  >=  <  <=  ==  ===  !=  !==
 *   - Logical operators:     &&  ||  !
 *   - Parenthesised sub-expressions
 *
 * Explicitly NOT supported (and will throw):
 *   - Any identifier other than "ctx"
 *   - Function calls, assignments, template literals, typeof, etc.
 */
function evalRule(expr, ctx) {
  if (typeof expr !== 'string' || expr.trim() === '') {
    throw new TypeError('"rule" must be a non-empty string');
  }
  const tokens = tokenise(expr.trim());
  return Boolean(parse(tokens, ctx));
}

// ---------------------------------------------------------------------------
// POST /check
// ---------------------------------------------------------------------------

/**
 * POST /check
 *
 * Request body (JSON):
 * {
 *   "rule":    "<expression>",   // required — rule expression (see evalRule above)
 *   "context": { ... }           // required — data object exposed as "ctx" in the rule
 * }
 *
 * Success response 200:
 * { "result": true | false }
 *
 * Error response 400:
 * { "error": "<message>" }
 */
app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({ error: '"rule" is required and must be a non-empty string' });
  }
  if (context === undefined || context === null || typeof context !== 'object') {
    return res.status(400).json({ error: '"context" is required and must be an object' });
  }

  let result;
  try {
    result = evalRule(rule, context);
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }

  return res.status(200).json({ result });
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});

module.exports = app; // export for testing

