  // numeric comparisons
  { rule: 'ctx.amount > 100',             ctx: { amount: 150 },           expect: true  },
  { rule: 'ctx.amount > 100',             ctx: { amount: 50  },           expect: false },
  { rule: 'ctx.amount >= 100',            ctx: { amount: 100 },           expect: true  },
  { rule: 'ctx.amount < 100',             ctx: { amount: 50  },           expect: true  },
  { rule: 'ctx.amount <= 99',             ctx: { amount: 100 },           expect: false },
  // string comparisons
  { rule: 'ctx.status === "active"',      ctx: { status: 'active' },      expect: true  },
  { rule: 'ctx.status !== "active"',      ctx: { status: 'inactive' },    expect: true  },
  { rule: "ctx.role == 'admin'",          ctx: { role: 'admin' },         expect: true  },
  // logical &&  ||
  { rule: 'ctx.a > 1 && ctx.b < 5',      ctx: { a: 2, b: 3 },            expect: true  },
  { rule: 'ctx.a > 1 && ctx.b < 5',      ctx: { a: 2, b: 6 },            expect: false },
  { rule: 'ctx.a > 1 || ctx.b < 5',      ctx: { a: 0, b: 3 },            expect: true  },
  { rule: 'ctx.a > 1 || ctx.b < 5',      ctx: { a: 0, b: 6 },            expect: false },
  // unary !
  { rule: '!ctx.flag',                    ctx: { flag: false },            expect: true  },
  { rule: '!ctx.flag',                    ctx: { flag: true  },            expect: false },
  // parentheses
  { rule: '(ctx.a > 1) && (ctx.b === "x")', ctx: { a: 5, b: 'x' },       expect: true  },
  { rule: '(ctx.a > 1) && (ctx.b === "x")', ctx: { a: 5, b: 'y' },       expect: false },
  // nested dotted path
  { rule: 'ctx.user.age >= 18',           ctx: { user: { age: 20 } },     expect: true  },
  { rule: 'ctx.user.age >= 18',           ctx: { user: { age: 16 } },     expect: false },
  // boolean literal
  { rule: 'ctx.active === true',          ctx: { active: true  },         expect: true  },
  { rule: 'ctx.active === true',          ctx: { active: false },         expect: false },
  // null literal
  { rule: 'ctx.val === null',             ctx: { val: null  },            expect: true  },
  { rule: 'ctx.val === null',             ctx: { val: 0     },            expect: false },
  // number literal on left
  { rule: '100 < ctx.amount',             ctx: { amount: 200 },           expect: true  },
