//
// Response:
// { "result": true | false }            200 OK
// { "error":  "<message>" }             400 Bad Request
// ---------------------------------------------------------------------------

// Allowed operators and their implementations (no eval / new Function).
const OPERATORS = {
  eq:         (a, b) => a === b,
  neq:        (a, b) => a !== b,
  gt:         (a, b) => a > b,
  gte:        (a, b) => a >= b,
  lt:         (a, b) => a < b,
  lte:        (a, b) => a <= b,
  contains:   (a, b) => typeof a === 'string' && typeof b === 'string' && a.includes(b),
  startsWith: (a, b) => typeof a === 'string' && typeof b === 'string' && a.startsWith(b),
  endsWith:   (a, b) => typeof a === 'string' && typeof b === 'string' && a.endsWith(b),
};

/**
 * Safely evaluate a structured rule against a plain-object context.
 *
 * @param {{ field: string, op: string, value: unknown }} rule
 * @param {Record<string, unknown>} context
 * @returns {{ result: boolean } | { error: string }}
 */
function evalRule(rule, context) {
  // --- input validation ---------------------------------------------------
  if (!rule || typeof rule !== 'object' || Array.isArray(rule)) {
    return { error: '`rule` must be an object' };
  }

  const { field, op, value } = rule;

  if (typeof field !== 'string' || field.trim() === '') {
    return { error: '`rule.field` must be a non-empty string' };
  }

  // Guard against prototype-pollution lookups like "__proto__" or "constructor"
  if (!Object.prototype.hasOwnProperty.call(context, field)) {
    return { error: `field "${field}" not found in context` };
  }

  if (typeof op !== 'string' || !Object.prototype.hasOwnProperty.call(OPERATORS, op)) {
    return { error: `unsupported operator "${op}"; allowed: ${Object.keys(OPERATORS).join(', ')}` };
  }

  if (value === undefined) {
    return { error: '`rule.value` is required' };
  }

  // --- evaluation ---------------------------------------------------------
  const fieldValue = context[field];
  const result = OPERATORS[op](fieldValue, value);
  return { result };
}

