//
// Example request body:
//   {
//     "context": { "amount": 150, "currency": "USD" },
//     "rule":    { "field": "amount", "op": "gt", "value": 100 }
//   }
// ---------------------------------------------------------------------------

/**
 * Safely resolve a dot-notation path from an object.
 * Only plain own-property traversal is allowed; prototype properties
 * (e.g. "__proto__", "constructor") are rejected.
 */
function resolvePath(obj, path) {
  const BLOCKED = new Set(['__proto__', 'constructor', 'prototype']);
  const parts = String(path).split('.');
  let current = obj;
  for (const part of parts) {
    if (BLOCKED.has(part)) return undefined;
    if (current === null || typeof current !== 'object') return undefined;
    if (!Object.prototype.hasOwnProperty.call(current, part)) return undefined;
    current = current[part];
  }
  return current;
}

/**
 * Evaluate a single declarative rule against the provided context object.
 * Returns a boolean result, or throws a descriptive Error on invalid input.
 */
function evalRule(context, rule) {
  if (!rule || typeof rule !== 'object' || Array.isArray(rule)) {
    throw new Error('rule must be a JSON object with "field", "op", and "value" properties');
  }

  const { field, op, value } = rule;

  if (typeof field !== 'string' || field.trim() === '') {
    throw new Error('"field" must be a non-empty string');
  }

  const ALLOWED_OPS = new Set(['eq', 'ne', 'gt', 'gte', 'lt', 'lte', 'contains', 'startsWith', 'endsWith']);
  if (!ALLOWED_OPS.has(op)) {
    throw new Error(`"op" must be one of: ${[...ALLOWED_OPS].join(', ')}`);
  }

