// keeping the evaluator completely isolated from the Node.js runtime.
// ---------------------------------------------------------------------------

/**
 * Resolve a dot-notation path (e.g. "user.age") against an object.
 * Returns `undefined` for missing paths; never throws.
 */
function resolvePath(obj, path) {
  return path.split('.').reduce(
    (cur, key) => (cur != null && Object.prototype.hasOwnProperty.call(cur, key) ? cur[key] : undefined),
    obj,
  );
