    if (expr[i] === '"' || expr[i] === "'") {
      const quote = expr[i++];
      let str = '';
      while (i < expr.length && expr[i] !== quote) {
        if (expr[i] === '\\') i++; // skip escape char
        str += expr[i++];
      }
      i++; // closing quote
      tokens.push({ type: 'STRING', value: str });
      continue;
    }

    // Multi-character operators (order matters: longer first)
    const multiOps = ['===', '!==', '>=', '<=', '&&', '||', '==', '!='];
    const slice = expr.slice(i);
    const matched = multiOps.find(op => slice.startsWith(op));
    if (matched) {
      tokens.push({ type: 'OP', value: matched });
      i += matched.length;
      continue;
    }

