// Rule engine — safe, declarative evaluator (NO dynamic code execution)
//
// A rule is a plain object describing a single comparison:
//   { "field": "amount", "op": "gt", "value": 100 }
//
// Supported ops: eq, neq, gt, gte, lt, lte, contains, startsWith, endsWith
//
// The `field` key is looked up in the caller-supplied `context` object.
// No caller-supplied code is ever executed.
// ---------------------------------------------------------------------------

const SUPPORTED_OPS = new Set([
  'eq', 'neq', 'gt', 'gte', 'lt', 'lte',
  'contains', 'startsWith', 'endsWith',
]);

/**
 * Safely resolve a dot-separated field path (e.g. "user.age") from an object.
 * Only plain own-property traversal is allowed; prototype keys are rejected.
 */
function resolvePath(obj, path) {
  const parts = String(path).split('.');
  let cur = obj;
  for (const part of parts) {
    if (cur === null || typeof cur !== 'object') return undefined;
    if (!Object.prototype.hasOwnProperty.call(cur, part)) return undefined;
    cur = cur[part];
  }
  return cur;
}

/**
 * Evaluate a single rule object against a context object.
 * Returns { result: boolean } or throws a descriptive Error for bad input.
 */
function evalRule(rule, context) {
  if (rule === null || typeof rule !== 'object' || Array.isArray(rule)) {
    throw new Error('"rule" must be a non-null object');
  }

  const { field, op, value } = rule;

  if (typeof field !== 'string' || field.trim() === '') {
    throw new Error('"rule.field" must be a non-empty string');
  }
  if (typeof op !== 'string' || !SUPPORTED_OPS.has(op)) {
    throw new Error(
      `"rule.op" must be one of: ${[...SUPPORTED_OPS].join(', ')}`
    );
  }
  if (value === undefined) {
    throw new Error('"rule.value" is required');
  }
  if (context === null || typeof context !== 'object' || Array.isArray(context)) {
    throw new Error('"context" must be a non-null object');
  }

  const fieldValue = resolvePath(context, field);

  switch (op) {
    case 'eq':         return fieldValue === value;
    case 'neq':        return fieldValue !== value;
    case 'gt':         return fieldValue >   value;
    case 'gte':        return fieldValue >=  value;
    case 'lt':         return fieldValue <   value;
    case 'lte':        return fieldValue <=  value;
    case 'contains':   return typeof fieldValue === 'string' && fieldValue.includes(String(value));
    case 'startsWith': return typeof fieldValue === 'string' && fieldValue.startsWith(String(value));
    case 'endsWith':   return typeof fieldValue === 'string' && fieldValue.endsWith(String(value));
    default:
      // Unreachable — SUPPORTED_OPS guard above covers this.
      throw new Error(`Unknown op: ${op}`);
  }
}

